```latex
\section{Preliminaries and Notation}
\label{sec:preliminaries}

\subsection{Notation}
\label{sec:notation}
We will denote the embedding of a point $x_i$ by $\embed[i]$, and sometimes by $\embed[x_i]$---both of these are supposed to stand for the same thing. We extensively make use of asymptotic notation $(\Omega(1), O(1))$ in the place of absolute constants.

\subsection{Metric Spaces of Interest}
\label{sec:metrics-prelims}
\begin{enumerate}
    \item $\ell_1$ metric: This metric space comprises of a set of $n$ points $\{x_1,\dots,x_n\} \subseteq \R^d$, where the distance function $d(x_i, x_j)=\|x_i-x_j\|_1=\sum_{k=1}^d|x_i[k]-x_j[k]|$.
    \item Tree metric: Consider an undirected edge-weighted tree $T_n$ on $n$ vertices $x_1,\dots,x_n$. Let $d(x_i, x_j)$ denote the standard graph distance on $T_n$, namely $d(x_i, x_j)=\sum_{e \in x_i \to x_j}e$, where the notation $e \in i \to j$ indexes the (weights on the) edges on the shortest path from $x_i$ to $x_j$.
\end{enumerate}

\subsubsection{Lipschitz Cap Metrics}
\label{sec:lipschitz-cap-metrics-prelims}
Let $M:S \to \R_{\ge 0}$ be a nonnegative cap function which satisfies the following \textit{Lipschitz} property: for any $x_i, x_j$ in $S$,
\begin{equation}
    \label{eqn:lipschitz-property}
    |M(x_i)-M(x_j)| \le d(x_i, x_j).
\end{equation}

\subsection{Caterpillar Tree Decomposition}
\label{sec:caterpillar-prelims}
Given an undirected tree $T_n$ on $n$ vertices $x_1,\dots,x_n$, let us arbitrarily root the tree at $x_1$. The caterpillar decomposition then decomposes the edges of the tree into several disjoint vertical paths called ``caterpillars", such that any root-to-leaf path touches at most $\log n$ caterpillars.

\section{General Tree Ising Models}
\label{sec:general-tim}

\subsection{Lipschitz Cap Metrics}
\label{sec:lipschitz-cap}

\subsubsection{Lipschitz Cap Tree Metrics}\label{sec:lipschitz-tree}

\textbf{Build-Clean-Tree Algorithm.}

\underline{\emph{Tree decomposition}}. We will again consider a modified caterpillar decomposition. Abusing notation slightly, we will refer to the caterpillars/segments given by the caterpillar decomposition as edges themselves. For any edge $e$ in the tree decomposition, we will denote $s(e)$ to be the location of the ``start'' (or top) of the edge, $\ell(e)$ the length of the edge, and $a(e)$ will store an auxiliary value for the edge we will later define. After obtaining the original caterpillar decomposition, we will split up any overly long edges. More concretely, we chop off any edge $e$ having length larger than $\frac{M(s(e))}{100\log(n)}$ at $\frac{M(s(e))}{100\log(n)}$, and then recursively continue chopping the remaining part of the edge. This process ensures that the length of every (potentially chopped) edge $e$ is at most $\frac{M(s(e))}{100\log(n)}$.
From this decomposition, we will create the embedding. \underline{All embeddings will be of length $|H| = 8 \log(n)$}. Consider building the embedding from the top to bottom, in a way such that we will only process an edge $e$ after its parent has been processed.

\underline{\emph{Building}}. One stage of our algorithm is \emph{building}. If we process an edge $e$ while the auxiliary information $a(e)$ indicates it is the building stage, we will then uniformly at random determine a hash for the edge $h(e) \in [8 \log(n)]$. Let $embedding[i](k)$ denote the $k^\text{th}$ coordinate of the embedding at location $i$. Then, we will proceed as follows:

\begin{itemize}
    \item If $embedding[s(e)](h(e)) = 0$, then we will walk in the positive direction for the coordinate $h(e)$ as traversing the edge. More formally, suppose $embedding[s(e)+v]$ denotes the embedding at $v$ below $s(e)$ for $v \in [0,\ell(e)]$. Then, we set $embedding[s(e)+v](h(e))=v$. All other coordinates remain the same as $embedding[s(e)]$.
    \item Otherwise, if $embedding[s(e)](h(e)) \ne 0$, then we do nothing and keep the embedding entirely the same as $embedding[s(e)]$.
\end{itemize}

\underline{\emph{Controlling stages}}.  We will design our stages such that build stages process $\lb = 4 \log(n)$ edges, and clean stages process $\lc = 9 \log(n)$ edges, and we alternate between building and cleaning. Our auxiliary information $a(e)$ will actually be an integer counter $\in \{0, \dots,\lb + \lc-1\}$, such that the edge will be processed in the build stage if $a(e) \in \{0,\dots, \lb-1\}$ and otherwise in the clean stage if $a(e) \in \{\lb,\dots,\lb+\lc-1\}$. Moreover, $a(e)$ will simply be $a(par(e))+1 \mod (\lb + \lc)$. 

\underline{\emph{Initialization}}. For technical reasons similar to those of the Lipschitz cap line metric, we will modify the tree so that the root $r$ of the original tree actually has a parent that is a new node $r_0$, where $M(r_0)=M(r)$ and the length of the edge $(r_0,r)$ is $2M(r)$. We initialize $embedding[r_0] = 0^{|H|}$. The auxiliary information of the topmost edge in the tree which contains the extra node $r_0$ is initialized uniformly at random in $\{0,\dots,\lb+\lc-1\}$.  

\begin{claim}[Caps on an edge are close by]\label{claim:edge-similar}
    For any edge $e = (u,w)$ in the decomposition with $u=s(e)$ and location $v$ along $e$, it must hold that $\frac{M(u)}{M(v)},\frac{M(v)}{M(u)} \le 1 + \frac{1}{50 \log(n)}$.
\end{claim}

For any locations $x$ and $y$ in the tree, let $P_{x \rightarrow y}$ denote the path from location $x$ to $y$, and let $\ell(P_{x \rightarrow y})$ denote the total length of the path.
```


