With this in mind, you are tasked to prove the following target statement.

Target Problem (your task):

\begin{subclaim}\label{subclaim:leg}
    Fix any two locations $x$ and $y$, and let $L=$LCA$(x,y)$ be the least common ancestor of $x$ and $y$. Then,
    $$\E[\|\embed[x]-\embed[y]\|_1] \ge \Omega(1) \cdot \min(\ell(P_{L \rightarrow x}),M(x)).$$
\end{subclaim}

ground_truth_solution:
We start by proving the following auxiliary statement:

\begin{claim}[Caps on a path are close by]\label{claim:path-similar}
    Consider a sequence of edges $e_1, \dots, e_k$, such that each $e_i,e_{i+1}$ is adjacent (meaning they share a vertex), and $x_1$ is on $e_1$ and $x_k$ is on $e_k$. Then, it must hold that $\frac{M(x_k)}{M(x_1)} \le e^{\frac{k}{50\log(n)}}$. As a special case, $\frac{M(s(e_k))}{M(s(e_1))} \le e^{\frac{k}{50\log(n)}}$.
\end{claim}
\begin{proof}
    Note how the adjacency condition in the sequence $e_1,\dots,e_k$ implies that it is possible to traverse from $x_1$ to $x_k$ by crossing at most $k$ edges. Thus, by \Cref{claim:edge-similar} it holds that:

    \begin{align}
        \frac{M(x_k)}{M(x_1)} &= \frac{M(x_k)}{M(s(e_k))}\cdot\frac{M(s(e_k))}{M(s(e_{k-1}))}\cdot\dots\cdot\frac{M(s(e_3))}{M(s(e_2))}\cdot\frac{M(s(e_2))}{M(x_1)} \\
        & \le \left(1 + \frac{1}{50 \log(n)}\right)^k \\
        & \le e^{\frac{k}{50 \log(n)}},
    \end{align}
    where in the last step, we used $1+x \le e^x$ for all real $x$.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
    If $x=L$, then $\ell(P_{L \rightarrow x})=0$, and the bound holds. Otherwise, consider the last $3\log(n)$ edges along the path $P_{L \rightarrow x}$ (or consider all the edges if there are less than $3\log(n)$). Now, consider the event that all these edges are ``build'' edges. Over the randomness of initializing $a(r_0)$, this must happen with probability at least $\frac{\lb - 3\log(n)}{\lb + \lc} = \Omega(1)$. Let us just consider the expected difference in embeddings conditioned on this constant-probability event.

    Let $\ell_P(e)$ denote the length of the edge that lies on the path $P_{L \rightarrow x}$ (this may be different than $\ell(e)$ if only a fraction of $e$ lies along $P_{L \rightarrow x}$). Observe that
    \begin{align*}
        \E[\|\embed[x]-\embed[y]\|_1] &= \sum_{i=1}^{H}\E[|\embed[x](i)-\embed[y](i)|]
    \end{align*}
    Now, for any fixed index $i \in \{1,\dots,H\}$, let $A_i$ be the event that exactly one of the last $k\le 3\log(n)$ edges $e_1,\dots,e_k$ along $P_{L \rightarrow x}$ hash to index $i$, but none of the other edges in the build stages immediately preceding both $x$ and $y$ hash to index $i$. Observe that
    \begin{align*}
        \Pr[A_i] &\ge \sum_{j=1}^{k}\frac{1}{H}\left( 1-\frac{1}{H}\right)^{2\lb}=\frac{k}{H}\left( 1-\frac{1}{H}\right)^{2\lb} = \frac{k}{H}\left(1-\frac{1}{8\log n}\right)^{8\log n}\ge \Omega(1)\cdot \frac{k}{H}.
    \end{align*}
    Furthermore, conditioned on $A_i$, observe that
    \begin{align*}
        \E\left[|\embed[x](i)-\embed[y](i)|~\bigg|~A_i\right] &= \frac{1}{k}\sum_{j=1}^k \ell_P(e_j),
    \end{align*}
    and thus,
    \begin{align*}
        \E[|\embed[x](i)-\embed[y](i)|] &\ge \Pr[A_i]\cdot \E\left[|\embed[x](i)-\embed[y](i)|~\bigg|~A_i\right] \\
        &\ge \Omega(1)\cdot \frac{k}{H}\cdot \frac{1}{k}\sum_{j=1}^k \ell_P(e_j) 
        = \Omega(1)\cdot \frac{1}{H}\sum_{j=1}^k\ell_P(e_j).
    \end{align*}
    Finally,
    \begin{align*}
        \E[\|\embed[x]-\embed[y]\|_1] &= \sum_{i=1}^{H}\E[|\embed[x](i)-\embed[y](i)|]
        \ge \Omega(1)\cdot \sum_{j=1}^k\ell_P(e_j).
    \end{align*}
    Thus, the claim is already proven by the above argument if there at most $k\le 3\log(n)$ edges on $P_{L \rightarrow x}$. If not, there are $> 3 \log(n)$ edges on $P_{L \rightarrow x}$, and if we look at the last $k=3 \log(n)$ of them, then there is at most one fractional edge (close to $x$) amongst these---all the rest are fully on $P$ i.e., $\ell_P(e)=\ell(e)$. Furthermore, by the caterpillar property, all but $\log(n)$ of these edges have length
    \begin{align}
        \ell_P(e_j) &= \frac{M(s(e))}{100 \log(n)} \\
        &= \frac{M(x)}{100 \log(n)} \cdot \frac{M(s(e))}{M(x)} \\
        & \ge \frac{M(x)}{100 \log(n)} \cdot e^{-2/50} \label{step:lb-by-path}\\
        & \ge \frac{M(x)}{200 \log(n)}
    \end{align}
    \Cref{step:lb-by-path} uses \Cref{claim:path-similar}. To conclude, 
    \begin{align*}
        \sum_{j=1}^k \ell_P(e) \ge (3\log(n)-1-\log(n)) \cdot \frac{M(x)}{200 \log(n)} = M(x)\left(\frac{1}{100} - \frac{1}{200 \log(n)}\right) = \Omega(M(x))
    \end{align*}
    for $n \ge 2$. In any case, we have shown
    \begin{align*}
        \E[\|\embed[x]-\embed[y]\|_1] \ge \Omega(1) \cdot \min(\ell(P_{L \rightarrow x}),M(x)).
    \end{align*}
\end{proof}
